using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public sealed class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker(reorderThreshold: 10);

    // ──────────────────────────────────────────────
    //  GetStockLevel
    // ──────────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN-001"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void GetStockLevel_NullSku_Throws()
    {
        _tracker.GetStockLevel(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void GetStockLevel_EmptySku_Throws()
    {
        _tracker.GetStockLevel(string.Empty);
    }

    // ──────────────────────────────────────────────
    //  AddStock
    // ──────────────────────────────────────────────

    [TestMethod]
    public void AddStock_NewSku_SetsLevel()
    {
        _tracker.AddStock("SKU-A", 25);
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-A", 5);
        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void AddStock_ZeroQuantity_Throws()
    {
        _tracker.AddStock("SKU-A", 0);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void AddStock_NegativeQuantity_Throws()
    {
        _tracker.AddStock("SKU-A", -5);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_NullSku_Throws()
    {
        _tracker.AddStock(null!, 1);
    }

    // ──────────────────────────────────────────────
    //  RemoveStock
    // ──────────────────────────────────────────────

    [TestMethod]
    public void RemoveStock_SufficientStock_DecreasesLevel()
    {
        _tracker.AddStock("SKU-B", 20);
        _tracker.RemoveStock("SKU-B", 8);
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    public void RemoveStock_EntireStock_LevelBecomesZero()
    {
        _tracker.AddStock("SKU-B", 5);
        _tracker.RemoveStock("SKU-B", 5);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public void RemoveStock_InsufficientStock_Throws()
    {
        _tracker.AddStock("SKU-B", 3);
        _tracker.RemoveStock("SKU-B", 10);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void RemoveStock_ZeroQuantity_Throws()
    {
        _tracker.RemoveStock("SKU-B", 0);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void RemoveStock_NegativeQuantity_Throws()
    {
        _tracker.RemoveStock("SKU-B", -1);
    }

    // ──────────────────────────────────────────────
    //  NeedsReorder
    // ──────────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-C", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-C"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-C", 10);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-C"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-C", 50);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-C"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("NEVER-STOCKED"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void NeedsReorder_NullSku_Throws()
    {
        _tracker.NeedsReorder(null!);
    }

    // ──────────────────────────────────────────────
    //  Constructor
    // ──────────────────────────────────────────────

    [TestMethod]
    public void Constructor_DefaultThreshold_IsAccepted()
    {
        var tracker = new InventoryTracker();
        tracker.AddStock("X", 11);
        Assert.IsFalse(tracker.NeedsReorder("X"));
    }

    [TestMethod]
    public void Constructor_CustomThreshold_IsRespected()
    {
        var tracker = new InventoryTracker(reorderThreshold: 50);
        tracker.AddStock("X", 30);
        Assert.IsTrue(tracker.NeedsReorder("X"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void Constructor_NegativeThreshold_Throws()
    {
        _ = new InventoryTracker(reorderThreshold: -1);
    }

    // ──────────────────────────────────────────────
    //  Warehouse Transfer
    // ──────────────────────────────────────────────

    [TestMethod]
    public void Transfer_MovesStockBetweenWarehouses()
    {
        var warehouseA = new InventoryTracker();
        var warehouseB = new InventoryTracker();

        warehouseA.AddStock("SKU-T", 100);
        InventoryTracker.Transfer(warehouseA, warehouseB, "SKU-T", 40);

        Assert.AreEqual(60, warehouseA.GetStockLevel("SKU-T"));
        Assert.AreEqual(40, warehouseB.GetStockLevel("SKU-T"));
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public void Transfer_InsufficientSourceStock_Throws()
    {
        var warehouseA = new InventoryTracker();
        var warehouseB = new InventoryTracker();

        warehouseA.AddStock("SKU-T", 5);
        InventoryTracker.Transfer(warehouseA, warehouseB, "SKU-T", 20);
    }

    [TestMethod]
    public void Transfer_FailureDoesNotModifyDestination()
    {
        var warehouseA = new InventoryTracker();
        var warehouseB = new InventoryTracker();

        warehouseA.AddStock("SKU-T", 5);

        try { InventoryTracker.Transfer(warehouseA, warehouseB, "SKU-T", 20); }
        catch (InvalidOperationException) { /* expected */ }

        Assert.AreEqual(0, warehouseB.GetStockLevel("SKU-T"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void Transfer_NullSource_Throws()
    {
        InventoryTracker.Transfer(null!, new InventoryTracker(), "SKU-T", 1);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void Transfer_NullDestination_Throws()
    {
        var tracker = new InventoryTracker();
        tracker.AddStock("SKU-T", 10);
        InventoryTracker.Transfer(tracker, null!, "SKU-T", 1);
    }
}

