        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _tracker.RemoveStock("SKU-B", 0));
    }

    [TestMethod]
    public void RemoveStock_NegativeQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _tracker.RemoveStock("SKU-B", -1));
    }

